// Average of the values that are real numbers.
function average(values) {
  const numbers = values.filter((v) => typeof v === 'number' && !Number.isNaN(v));
  if (numbers.length === 0) return null;
  let total = 0;
  for (const n of numbers) total += n;
  return total / numbers.length;
}

console.log(average([3, 5, 8]));   // 5.333...
console.log(average([]));          // null

from collections import Counter


def top_words(text, limit=5):
    """Return the most common words, ignoring case and punctuation."""
    words = [w.strip(".,;:!?\"'()").lower() for w in text.split()]
    counts = Counter(w for w in words if w)
    return counts.most_common(limit)


if __name__ == "__main__":
    sample = "The tide is out, the gulls are loud; the boats are in."
    for word, n in top_words(sample, 3):
        print(f"{word:>8} {n}")

type Range = { readonly start: number; readonly end: number };

export function overlaps(a: Range, b: Range): boolean {
  return a.start < b.end && b.start < a.end;
}

export function merge(ranges: Range[]): Range[] {
  const sorted = [...ranges].sort((x, y) => x.start - y.start);
  const out: Range[] = [];
  for (const r of sorted) {
    const last = out[out.length - 1];
    if (last && r.start <= last.end) {
      out[out.length - 1] = { start: last.start, end: Math.max(last.end, r.end) };
    } else {
      out.push(r);
    }
  }
  return out;
}
